pacing--60)\"><!-- wp:heading {\"align\":\"wide\"} -->\n<h2 class=\"wp-block-heading alignwide\">Our classes</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":7,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/lume/website/wp-content/uploads/2026/09/mat_pilates.jpg\" alt=\"Mat Pilates\" class=\"wp-image-7\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Mat Pilates</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Exercises on a mat. The best class to start with.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":8,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/lume/website/wp-content/uploads/2026/09/reformer_pilates.jpg\" alt=\"Reformer Pilates\" class=\"wp-image-8\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Reformer Pilates</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Exercises on a reformer machine, in small groups.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":9,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/lume/website/wp-content/uploads/2026/09/barre.jpg\" alt=\"Barre\" class=\"wp-image-9\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Barre</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Small movements at a ballet bar. Good for balance.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":10,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/lume/website/wp-content/uploads/2026/09/prenatal_pilates.jpg\" alt=\"Prenatal Pilates\" class=\"wp-image-10\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Prenatal Pilates</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Gentle and safe exercise during pregnancy.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:media-text {\"align\":\"wide\",\"mediaId\":6,\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://localhost/lume/website/wp-content/uploads/2026/09/studio.jpg\" alt=\"A woman on a reformer in the studio\" class=\"wp-image-6 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A calm place to get strong</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Small classes, so every person gets help</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Good instructors for every kind of class</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>For beginners and for experienced people</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#C0684A\",\"text\":\"#ffffff\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-color has-background wp-element-button\" href=\"/lume/website/schedule/\" style=\"color:#ffffff;background-color:#C0684A\">See the schedule</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\